/** Look a payload up by manifest id. Throws rather than pushing `undefined`. */
export function payloadById(id: string): GeneratedPayload {
  const p = GENERATED_PAYLOADS.find((x) => x.id === id);
  if (!p) throw new Error(`no generated payload with id "${id}"`);
  return p;
}
